(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pl"] = {"ui":{"skip":"Przejdź do treści","back":"← Wróć do AI-gile","lang.button":"Język: {name}","lang.dialog":"Wybierz język","lang.search":"Szukaj języków","lang.none":"Nie znaleziono języka","lang.notYet":"{name} nie jest jeszcze przetłumaczony","theme.aria":"Przełącz motyw: jasny, ciemny lub czarny","theme.toLight":"Przełącz na jasny motyw","theme.toDark":"Przełącz na ciemny motyw","theme.toBlack":"Przełącz na czarny motyw (prawdziwa czerń, przyjazna ekranom OLED)","words.underline":"Podkreśl te słowa na stronie","words.underlineHelp":"Najedź kursorem na słowo z kropkowanym podkreśleniem albo je dotknij, żeby zobaczyć, co znaczy.","index.title":"AI-gile: Twój zespół AI do programowania, na jednej tablicy","index.description":"AI-gile to tablica kanban dla zespołów programistycznych AI. Pracują, gdy Ty śpisz; Ty dostajesz jeden krótki stos spraw do rozstrzygnięcia, przetestowania i zaakceptowania.","hero.logoAlt":"Ikona tablicy AI-gile","hero.h1.html":"Twój zespół AI do programowania, na jednej&nbsp;tablicy.","hero.alpha":"🐣 Zamknięta pre-alfa","hero.alphaTitle":"Wczesna i niedokończona: dzięki, że próbujesz!","hero.lede":"Budują, gdy śpisz. Budzisz się przy jednym krótkim stosie: kilka pytań, kilka rzeczy do przetestowania, fioletowy diament czy dwa. Klik, akceptacja i z powrotem do kawy.","dl.windows":"Aplikacja na Windows","dl.browser":"Uruchom w przeglądarce","dl.messenger":"📱 Messenger na telefon","dl.soon":"Wkrótce","dl.notify":"🔔 Powiadom mnie, gdy ruszy","dl.notifySmall":"Alfa lub beta","hero.secondary":"Agile, ale zespół nigdy nie potrzebuje kawy na stojąco. (I tak robią stand-upy.)","pitch.h2":"AI-gile w tylu słowach, ilu chcesz","pitch.lede":"Wybierz długość, od jednego słowa do 144. Każda długość to osobny opis, napisany właśnie na ten rozmiar. Przeciągnij suwak albo użyj strzałek.","pitch.rangeLabel":"Długość w słowach","pitch.dice":"🎲 inna wersja","pitch.words.one":"{n} słowo","pitch.words.other":"{n} słowa","pitch.letters.one":"{n} litera","pitch.letters.other":"{n} litery","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znaku","count.line.html.one":"{n} karta na tablicy w tej chwili","count.line.html.other":"{n} karty na tablicy w tej chwili","people.humans.html.one":"👥 {n} osoba","people.humans.html.other":"👥 {n} osób","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agentów","people.working.html.one":"⚡ {n} w pracy w tej chwili","people.working.html.other":"⚡ {n} w pracy w tej chwili","pre.title":"AI-gile: coś tu powstaje","pre.description":"Coś tu powstaje: tablica, na której zespoły AI budują to, o co prosisz, i przy okazji cię uczą. Na razie zamknięta pre-alfa z przyjaciółmi.","pre.h1":"Coś tu powstaje. 🤫","pre.line":"Tablica, na której zespoły AI budują to, o co prosisz, i przy okazji cię uczą. Na razie zamknięta pre-alfa z przyjaciółmi.","pre.btn":"🔔 Powiadom mnie, gdy ruszy","pre.peek":"Za szybą: prawdziwa tablica, na żywo. Każda karta to kolorowy pasek.","pre.peekFake":"Za szybą: tak wygląda tablica w akcji.","features.aria":"Co robi","f.pile.h":"Jeden stos dla Ciebie","f.pile.html":"<b>Dla Ciebie</b> zbiera wszystko, co czeka na Ciebie, we wszystkich projektach: pytania, rzeczy do przetestowania, zadania tylko dla człowieka. Twoja kolejka mówi, co dalej i ile to zajmie.","f.sleep.h":"Zespoły, które pracują, gdy śpisz","f.sleep.p":"Każdy projekt ma lidera i zespół agentów AI. Skomentuj kartę, a zespół się budzi, robi swoje i oddaje ją z krokami, które zrozumie zmęczony człowiek.","f.tester.h":"Najpierw sprawdza tester AI","f.tester.p":"Zanim cokolwiek do Ciebie trafi, tester wykonuje kroki w kopii aplikacji i pokazuje, co zobaczył, ze zrzutem ekranu. Przejrzyj te, które przeszły, i zaakceptuj jednym kliknięciem.","f.proof.h":"Dowody, nie obietnice","f.proof.p":"Każde przekazanie pokazuje, co się zmieniło: pliki, diff, zrzuty ekranu. Bez otwierania każdej aplikacji, żeby sprawdzić, czy już gotowe.","f.chat.h":"Rozmawiaj ze swoimi liderami","f.chat.p":"Pasek w stylu Discorda: jedna ikona na projekt, fioletowe diamenty przy tym, co czeka na Ciebie. Napisz do lidera pomysł; zamieni go w karty i plan, z przyciskiem ✅ Go.","f.tidy.h":"Sam dba o porządek","f.tidy.p":"Powiązane karty zlewają się w jedną, zagmatwane tytuły są poprawiane, a kontrola tokenów utrzymuje kod szczupłym. Mniej rzeczy do przełączania, mniej do myślenia.","f.private.h":"Twoje, na Twoim komputerze","f.private.li1":"Tablica działa na Twojej własnej maszynie i odpowiada tylko Tobie.","f.private.li2":"Prywatne wiadomości między ludźmi są szyfrowane od końca do końca.","f.private.li3":"Bez kont, bez trackerów, bez ciasteczek.","f.lang.h":"W Twoim języku","f.lang.p":"Ponad 120 języków, od niderlandzkiego, walijskiego i japońskiego po piracki, Yodę i klingoński, z szybkim przełącznikiem na angielski dla żargonu branżowego.","f.service.h":"Od pomysłu do prawdziwej usługi","f.service.p":"Udało Ci się zbudować z AI coś, z czego ludzie już korzystają? Oznacz to jako usługę, a tablica pomoże Ci dobrze ją prowadzić: sprawdzanie dostępności, publiczna strona statusu, incydenty z opisem, zmiany, które wymagają Go, kopie zapasowe sprawdzane codziennie. Pomoc uczy każdego kroku po drodze.","msgr.h2":"AI-gile Messenger: Twój zespół w kieszeni","msgr.p1":"Rozmawiaj ze swoim zespołem AI bez otwierania tablicy. Czatuj z liderami projektów i znajomymi, przeglądaj kroki testowe kart i odpowiadaj na nie, wszystko z telefonu.","msgr.p2":"Aby go sparować, zeskanuj kod QR na swojej tablicy. Pierwszy raz? Przyjazny czat demo wszystko Ci pokaże.","msgr.when":"Najpierw Android, potem wersja przeglądarkowa na telefony i iPhone.","msgr.who":"Twój lider projektu","msgr.b1":"Poprawka trybu ciemnego jest gotowa. Podesłać kroki testowe?","msgr.b2":"Tak, poproszę!","msgr.b3":"1. Otwórz Ustawienia. 2. Wybierz Ciemny. Wygląda dobrze?","tl.aria":"Oś czasu od pierwszej rozmowy do planów","tl.h2":"Od pierwszej rozmowy do tego, co dalej","tl.lede":"Prawdziwe daty i godziny, w Twojej strefie czasowej. Po dzisiejszym dniu to plan, bez obiecywanych dat.","tl.today":"Dziś","tl.planned":"w planach","tl.doing":"w toku","tl.cards.one":"{n} karta","tl.cards.other":"{n} karty","join.h2":"Dołącz","join.lede":"AI-gile budują brodaty dziwak z AuDHD i kilkoma bitwami o zdrowie psychiczne oraz bardzo wielu cierpliwych agentów. Na razie jest prywatne, w zamkniętej alfie z przyjaciółmi. Chcesz spróbować, gdy się otworzy?","join.btn":"Zgłoś zainteresowanie","join.small":"Napiszemy do Ciebie e-mailem i nic więcej","footer.tag":"AI-gile. Bez trackerów, bez ciasteczek, bez kawy na stojąco.","footer.licence":"Licencja biznesowa","footer.status":"Status","footer.privacy":"Co przechowujemy","footer.thanks":"Rozmowy dzięki ChilledChat","form.sending":"Wysyłanie…","form.failed":"Nie udało się: spróbuj ponownie później.","form.offline":"Nie można połączyć się z AI-gile: spróbuj ponownie później.","form.keep":"Używamy tego tylko po to, żeby Ci odpowiedzieć, a potem to usuwamy. Bez trackerów, bez ciasteczek.","form.keepLink":"Co przechowujemy","interest.title":"AI-gile: powiadom mnie, gdy ruszy alfa","interest.description":"Zostaw e-mail, żeby dowiedzieć się, kiedy ruszy zamknięta alfa lub beta AI-gile.","interest.h1":"🔔 Powiadom mnie, gdy ruszy","interest.lede":"AI-gile jest w zamkniętej pre-alfie. Zostaw e-mail, a napiszemy raz, gdy znajdzie się dla Ciebie miejsce.","interest.email":"Twój e-mail","interest.which":"Który test?","interest.alpha":"Zamknięta alfa: wcześnie, surowo, dużo zmian","interest.beta":"Beta: spokojniej, później","interest.both":"Obojętnie, co pierwsze","interest.submit":"Zapisz mnie na listę","interest.thanks":"Dzięki! Jesteś na liście.","licence.title":"AI-gile: licencja biznesowa","licence.description":"Używasz AI-gile w firmie? Poproś o bezpłatną licencję biznesową.","licence.h1":"📜 Licencja biznesowa","licence.lede":"Używasz AI-gile w pracy? Napisz, kim jesteś i czym się zajmujesz. Jeśli robi to coś dobrego, licencja jest bezpłatna.","licence.company":"Firma","licence.website":"Strona internetowa","licence.what":"Czym się zajmujesz","licence.how":"Jak to pomaga światu","licence.email":"E-mail","licence.submit":"Wyślij wniosek","licence.thanks":"Dzięki! Odpowiemy e-mailem.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Wszystko spokojnie","status.intro":"Czy AI-gile teraz działa? Ta strona co 5 minut sprawdza stronę internetową, udostępnianie tablic, rozmowy i pobieranie.","status.up":"Działa (odpowiedź w {ms} ms)","status.slow":"Brak odpowiedzi przy ostatnim sprawdzeniu, ponawiam","status.down":"Nie działa: brak odpowiedzi przy dwóch ostatnich sprawdzeniach","status.svc.web":"Strona internetowa","status.svc.web.offers":"Ta strona: czym jest AI-gile i formularz zgłoszeniowy","status.svc.boards":"Udostępnianie tablic","status.svc.boards.offers":"Publiczne tablice, wiadomości między znajomymi i zaproszenia","status.svc.calls":"Rozmowy","status.svc.calls.offers":"Głos, wideo i udostępnianie ekranu w AI-gile","status.svc.download":"Pobieranie","status.svc.download.offers":"Instalator na Windows i linki z zaproszeniami","status.checking":"Sprawdzanie…","status.offline":"Nie można teraz połączyć się z usługą statusu (ponawiam)","status.updated":"zaktualizowano {ago}","status.justNow":"przed chwilą","status.min":"{n} min temu","status.hours":"{n} godz. temu","status.days":"{n} dni temu","privacy.title":"AI-gile: co przechowujemy","privacy.h1":"Co przechowujemy","privacy.lede":"W skrócie: tylko to, co nam wyślesz, i nie na długo.","privacy.only":"Tylko to, co nam wyślesz: to, co wpiszesz w formularz, na przykład Twój e-mail. Nic więcej o Tobie.","privacy.sealed":"Dane są zapieczętowane, więc nasz serwer nie może ich odczytać: w Twojej przeglądarce, zanim zostaną wysłane (w starszej przeglądarce w chwili, gdy dotrą). Otworzyć je może tylko nasza własna tablica.","privacy.server":"Usuwamy je z serwera, gdy tylko dotrą do naszej tablicy. Wszystko, co leży tam dłużej niż 30 dni, i tak zostaje usunięte.","privacy.board":"Trzymamy je na naszej tablicy tylko do czasu, aż Ci odpowiemy, a potem usuwamy je również stamtąd.","privacy.none":"Bez trackerów, bez ciasteczek, bez analityki.","privacy.local":"Twój język i wybór jasnego lub ciemnego motywu zostają w Twojej przeglądarce. Nigdy nie są do nas wysyłane.","privacy.ask":"Chcesz, żeby zniknęły wcześniej? Odpowiedz na naszego e-maila i daj znać.","live.h2":"Zobacz, jak to powstaje, na żywo","live.caption":"Każda karta jest ukryta: widzisz kształt pracy, a nie słowa.","live.watching.one":"na żywo: ogląda {n}","live.watching.other":"na żywo: oglądają {n}","live.last.now":"Ostatnia karta przesunięta przed chwilą","live.last.min.one":"Ostatnia karta przesunięta {n} min temu","live.last.min.other":"Ostatnia karta przesunięta {n} min temu","live.last.hour.one":"Ostatnia karta przesunięta {n} godz. temu","live.last.hour.other":"Ostatnia karta przesunięta {n} godz. temu","live.last.day.one":"Ostatnia karta przesunięta {n} dzień temu","live.last.day.other":"Ostatnia karta przesunięta {n} dni temu","live.offline":"Tablica na żywo bierze krótki oddech. Zajrzyj wkrótce ponownie.","live.cols":"Backlog|Do zrobienia|W toku|Zespół sprawdza|Do przetestowania przez Ciebie|Dla zespołu|Gotowe","pitch.words.few":"{n} słowa","pitch.words.many":"{n} słów","pitch.letters.few":"{n} litery","pitch.letters.many":"{n} liter","pitch.chars.few":"{n} znaki","pitch.chars.many":"{n} znaków","count.line.html.few":"{n} karty na tablicy w tej chwili","count.line.html.many":"{n} kart na tablicy w tej chwili","tl.cards.few":"{n} karty","tl.cards.many":"{n} kart"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboty.","Zlecone."]},{"n":2,"texts":["Kanban robotów.","Agenci, uporządkowani.","Pomysły, zbudowane."]},{"n":3,"texts":["Kanban dla robotów.","Pomysły stają się funkcjami.","Darmowy kanban agentów."]},{"n":5,"texts":["Tablica kanban prowadzona przez agentów.","Ty piszesz karty. Agenci budują.","Darmowe, lokalne, testowane, odrobinę zwariowane."]},{"n":8,"texts":["Darmowy kanban, w którym pracują agenci AI.","Zapisz pomysł. Agenci go zbudują. Ty akceptujesz.","Agile dla jednego człowieka i wielu cierpliwych robotów."]},{"n":13,"texts":["Tablica kanban na Twoim komputerze, gdzie karty biorą agenci AI.","Zapisz swój pomysł na karcie. Cały zespół agentów go zbuduje, a tester AI sprawdzi, czy działa.","Za darmo, bez kont, bez trackerów: tablica, trochę robotów i Ty u steru."]},{"n":21,"texts":["AI-gile to tablica kanban do pracy z agentami programistycznymi AI. Oni biorą karty; Ty testujesz i akceptujesz.","Każdy projekt dostaje lidera i zespół agentów AI. Skomentuj dowolną kartę, a zespół bierze się do pracy.","Darmowa, osobista tablica zadań, która działa na Twoim własnym komputerze, bez żadnych kont. Pracują roboty, ale to Ty decydujesz, co jest gotowe."]},{"n":34,"texts":["Wrzucasz pomysły na tablicę. Zespół agentów AI zamienia je w działające funkcje, testuje i oddaje z krokami do wypróbowania. Nic nie liczy się jako zrobione, dopóki Ty tego nie powiesz.","AI-gile to domowa tablica kanban, którą Rich zbudował przy ogromnej pomocy agentów, którymi teraz zarządza. Jest darmowa, działa na Twoim komputerze i jest dzielona z przyjaciółmi, a nie sprzedawana.","Wyobraź sobie zwykłą tablicę kanban z kolumnami od Backlogu do Gotowe, tyle że karty biorą agenci AI. Zgłaszają postępy, pytają, gdy utkną, i zawsze czekają na Twój kciuk w górę."]},{"n":55,"texts":["AI-gile to tablica kanban, na której zespół składa się z agentów AI. Każdy projekt ma lidera, który planuje pracę, i pomocników, którzy ją wykonują. Gdy funkcja jest gotowa, tester AI ją wypróbowuje i robi zrzut ekranu, a potem trafia na Twój stos. Zaakceptuj ją albo skomentuj, a oni poprawią.","Zaczęło się jako sposób jednej osoby na ogarnięcie wielu sesji programowania z AI naraz, a urosło do prawdziwej tablicy. Działa na Twojej maszynie, nie wymaga konta i nie ma trackerów. Jest darmowa dla przyjaciół i ciekawskich. Jest też niedokończona, więc spodziewaj się chropowatości i od czasu do czasu niespodzianki.","Powiedzmy sobie szczerze. Pomysły nadal musisz mieć sam i wyniki nadal musisz sprawdzać. AI-gile robi wszystko pomiędzy: trzyma karty w porządku, budzi właściwego agenta, gdy napiszesz komentarz, pokazuje dokładnie, co się zmieniło, i zbiera całą resztę w jeden krótki stos, który czeka właśnie na Ciebie."]},{"n":89,"texts":["AI-gile to darmowa tablica kanban, którą uruchamiasz na własnym komputerze. Zamiast ludzi każdy projekt ma zespół agentów AI: lidera, który zamienia Twoje pomysły w karty i plan, oraz pomocników, którzy biorą karty według priorytetu. Gdy coś jest zbudowane, tester AI wykonuje kroki testowe i pokazuje, co zobaczył. Potem całość czeka na jednym stosie zwanym Dla Ciebie. Akceptujesz albo komentujesz, a zespół próbuje jeszcze raz. Nic nie trafia do Gotowe bez Ciebie.","Kilka rzeczy, których możesz się nie spodziewać. Nocna straż uzupełnia kolumnę Do zrobienia, gdy śpisz, wybierając karty, które nie potrzebują Twojej odpowiedzi. Licznik tokenów pokazuje, ile agenci zużyli dziś i w tym tygodniu, a Tryb bez tokenów każe im przestać wydawać. Możesz pisać do przyjaciół, a prywatne wiadomości są szyfrowane od końca do końca. Tablica mówi w około 120 językach, w tym po niderlandzku, flamandzku, piracku i klingońsku. Nic z tego nie kosztuje ani grosza i nikt nie chce Ci tego sprzedać.","AI-gile to mały, osobisty projekt, a nie firma. Rich chciał opiekować się kilkoma projektami z AI bez otwierania każdej aplikacji osobno, żeby zobaczyć, co słychać, więc razem z agentami zbudował do tego tablicę, a potem tą samą tablicą zbudował resztę jej samej. Jest w zamkniętej pre-alfie, czyli działa, przeważnie, dla garstki przyjaciół. Nie ma cennika, newslettera ani planu podbijania świata. Jeśli brzmi to przydatnie, poproś o dostęp, gdy otworzy się trochę szerzej."]},{"n":144,"texts":["AI-gile to tablica kanban dla jednego człowieka i bardzo wielu agentów AI. Działa na Twoim własnym komputerze i jest całkowicie darmowa. Dodajesz projekty, a każdy projekt dostaje lidera i mały zespół. Rozmawiasz z liderem, trochę jak na Discordzie, i opisujesz swój pomysł; lider zamienia go w karty i plan, po czym czeka, aż naciśniesz Go. Zespół przechodzi przez karty według priorytetu, korzystając z prostego wiersza poleceń stworzonego dla modeli językowych. Zanim cokolwiek wróci do Ciebie, tester AI wykonuje wszystkie kroki w kopii aplikacji i dołącza zrzut ekranu tego, co zobaczył. Gotowa praca ląduje na Twoim stosie razem ze zmienionymi plikami i diffem. Akceptujesz ją albo zostawiasz komentarz, a wtedy zespół się budzi i próbuje jeszcze raz. Tylko Ty możesz przenieść kartę do kolumny Gotowe, nikt inny i nigdy.","Dzień z AI-gile, mniej więcej. Wieczorem zostawiasz kilka komentarzy: ten przycisk jest w złym miejscu, tamta lista powinna być posortowana, a czy mógłby być tryb ciemny. Idziesz spać. Agenci czytają komentarze, wprowadzają zmiany, testują je i oddają Ci wyniki. Jeśli kolumna Do zrobienia się opróżni, nocna straż uzupełnia ją kartami z backlogu, które nie potrzebują Twojej odpowiedzi. Rano czeka jeden krótki stos: kilka pytań i kilka rzeczy do wypróbowania, każda z krokami, za którymi trafi nawet niewyspana osoba, i ze zrzutem ekranu działającej wersji. Przeklikujesz wszystko, akceptujesz to, co dobre, i odsyłasz resztę. Licznik tokenów pokazuje, ile to wszystko zużyło, a Tryb bez tokenów czeka na chudsze tygodnie. Potem jesz śniadanie, w czym agenci jeszcze Ci nie pomogą.","Najpierw to, czym AI-gile nie jest. Nie jest startupem, nie jest na sprzedaż i nikt nie zbiera Twoich danych. To darmowa tablica, która działa na Twoim komputerze, bez kont, bez trackerów i bez ciasteczek. A czym jest: jednym uporządkowanym miejscem, w którym widzisz wszystkie projekty z AI naraz, z zespołem agentów robiącym karty i Tobą podejmującym decyzje. Łączy powiązane karty, poprawia zagmatwane tytuły i pilnuje, żeby kod pozostał szczupły. Mówi w około 120 językach, od niderlandzkiego i flamandzkiego po piracki i klingoński. Przyjaciele mogą do siebie pisać, prywatnie i szyfrowanie. Zbudowali ją Rich i bardzo wielu cierpliwych agentów, głównie korzystając z niej samej. Jest w zamkniętej pre-alfie, więc w niektórych miejscach bywa surowa. Jeśli brzmi to zabawnie, poproś ładnie, a może wejdziesz wcześniej."]}],"quips":{"1":"Jedno słowo. Odważnie. Może za odważnie.","3":"Trzy słowa. Już szczerzej niż większość stron produktów.","8":"Osiem słów. Nadal krócej niż stand-up.","21":"Długości to zresztą story pointy. Oczywiście, że tak.","55":"Pięćdziesiąt pięć słów. Dwie karty skończyły się, gdy to czytasz.","144":"To ta długa. Nie ma 233. Agenci poszli spać."}},"timeline":{"first-idea.name":"Pierwszy pomysł","first-idea.line":"Najpierwsza rozmowa, zanim powstała choćby linijka kodu.","first-board.name":"Pierwsza tablica","first-board.line":"Tablica, która śledzi własną budowę: karty, kolumny, przeciąganie, projekty.","team-roles.name":"Zespół i role","team-roles.line":"Profile agentów, szablony zespołów, przestrzenie i kto za co odpowiada.","install.name":"Instalacja i wydania","install.line":"Zip, który przyjaciel zainstaluje, z samoaktualizacją, kanałami i cofaniem.","usage-saver.name":"Oszczędzanie zużycia","usage-saver.line":"Mierzenie kosztu uruchomień, szczupły kod, oszczędzanie limitu.","friends.name":"Przyjaciele i udostępnianie","friends.line":"Prywatne wiadomości, zaszyfrowany przekaźnik, zaproszenia, role i wspólne projekty.","languages.name":"Języki","languages.line":"Każdy tekst na ekranie w pliku językowym, na początek niderlandzki i flamandzki.","ai-tester.name":"Tester AI","ai-tester.line":"Tester sprawdza każde przekazanie jako pierwszy i pokazuje, co zobaczył.","website.name":"Strona internetowa","website.line":"aigile.lol, strona zapowiedzi i ta oś czasu.","streaming.name":"Czat i streaming","streaming.line":"Discord, Twitch, OBS, tryb streamera, GIF-y i emoji.","no-ai.name":"Wersja bez AI","no-ai.line":"Tablica dla ludzi, którzy programują bez AI, oraz tablice publiczne.","night-watch.name":"Nocna straż","night-watch.line":"Stróż i Scrum Master pilnują zespołów, gdy śpisz.","p-more.name":"Cała reszta","p-more.line":"Mniejsze pomysły, które wciąż czekają na swoją kolej.","p-android.name":"Telefon i Android","p-android.line":"Dostęp do tablicy z telefonu, a potem natywna aplikacja na Androida.","p-release.name":"Alfa i dalej","p-release.line":"Zamknięta alfa, strona na żywo, potem beta.","p-languages.name":"Więcej języków","p-languages.line":"Ponad sto języków i tryb immersji dla uczących się.","p-engines.name":"Więcej silników AI","p-engines.line":"Wybierz Claude, Codex lub Gemini dla każdego agenta.","p-pro.name":"Praktyka zawodowa","p-pro.line":"Etykiety ryzyka, bramki scalania, karty incydentów i bariery ochronne.","p-self.name":"Dbanie o Ciebie","p-self.line":"Tryb zmęczenia, przypomnienia o dbaniu o siebie i 4:20.","p-servers.name":"Serwery i skala","p-servers.line":"Globalne ustawienia serwera, role i planowanie wzrostu.","p-livestream.name":"Dodatki do streamów","p-livestream.line":"Czat Twitcha, własne emoji i publiczny podgląd na żywo."},"words":{"button":"📖 Żargon branżowy","h":"📖 Słowniczek","intro":"Słowa, które spotkasz w AI-gile, prostym językiem: budowanie, bezpieczne wprowadzanie zmian, utrzymanie działania dla ludzi, którzy z tego korzystają, i praca w zespole z AI.","search":"Szukaj słowa…","none":"Żadne słowo nie pasuje.","close":"Zamknij","count":{"one":"{count} słowo","other":"Słów: {count}"},"groups":[{"id":"build","name":"🛠️ Budowanie"},{"id":"change","name":"🔀 Bezpieczne zmiany"},{"id":"run","name":"🛎️ Utrzymanie usługi"},{"id":"team","name":"🤝 Praca w zespole (i z AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folder projektu z kodem i pełną historią commitów, zwykle trzymany też na GitHubie.","also":["repozytorium"]},{"id":"branch","g":"build","word":"Branch","text":"Osobna linia pracy w kodzie, żeby zmieniać rzeczy bez dotykania głównej wersji.","also":["branche","gałąź","gałęzie"]},{"id":"commit","g":"build","word":"Commit","text":"Zapisana migawka kodu z krótką notatką o tym, co się zmieniło. Zawsze możesz do niej wrócić.","also":["commity"]},{"id":"push","g":"build","word":"Push","text":"Wysłanie zapisanych migawek (commitów) z tego komputera na GitHub, żeby były zabezpieczone i udostępnione."},{"id":"merge","g":"build","word":"Merge","text":"Włączenie zmian z brancha z powrotem do głównej wersji."},{"id":"pr","g":"build","word":"Pull request","text":"Prośba o sprawdzenie zmian z brancha i włączenie ich do głównej wersji.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoryzacja","text":"Porządkowanie kodu bez zmiany tego, co robi: mniejsze pliki, jaśniejsze nazwy, mniej powtórzeń."},{"id":"bug","g":"build","word":"Bug","text":"Coś, co nie działa tak, jak powinno.","also":["bugi","błąd","błędy"]},{"id":"test","g":"build","word":"Test","text":"Wypróbowanie skończonej pracy, by sprawdzić, czy robi to, czego oczekiwano, zanim ją zaakceptujesz.","also":["testy","testowanie"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Skrót od quality assurance, czyli zapewnienie jakości: automatyczne sprawdzenia, które działają, zanim cokolwiek pójdzie na żywo. Gdy QA jest czerwone, coś się nie udało i nie można tego wypuścić, dopóki nie zostanie naprawione.","also":["kontrola jakości","testy jakości"]},{"id":"deploy","g":"change","word":"Deploy","text":"Wypuszczenie nowej wersji na żywo, na przykład na serwer, z którego korzystają ludzie."},{"id":"release","g":"change","word":"Wydanie","text":"Nazwana paczka gotowej pracy, która idzie na żywo razem, z krótkimi notatkami o tym, co się zmieniło. 🚀 Wydania pisze notatki na podstawie zrobionych kart.","also":["wydania","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Powrót do ostatniej wersji, która działała, gdy nowa sprawia kłopoty. W AI-gile powstaje z tego lista kroków cofania, zapisanych przy każdej zmianie.","also":["wycofanie","cofnięcie zmian","wycofać"]},{"id":"live","g":"change","word":"Na żywo","text":"Prawdziwa wersja, z której korzystają ludzie, w odróżnieniu od kopii do próbowania. Programiści mówią na nią też produkcja.","also":["produkcja","prod"],"noTip":1},{"id":"change","g":"change","word":"Zmiana","text":"Zaplanowana zmiana w czymś, na czym ludzie polegają, najpierw spisana: co, dlaczego, ryzyko, kiedy i jak ją cofnąć. Zacznij od 🔀 Zgłoś zmianę.","also":["zmiany","wniosek o zmianę","change request"],"noTip":1},{"id":"risk","g":"change","word":"Ryzyko","text":"Coś, co może pójść nie tak, ocenione według tego, jak jest prawdopodobne i jak poważne by było. ⚠️ Ryzyka trzyma je na jednej liście, od najwyższej oceny, każde z datą ponownego przejrzenia.","also":["ryzyka","rejestr ryzyk"]},{"id":"chgwin","g":"change","word":"Okno zmian","text":"Pory, w których zmiany mogą iść na żywo, na przykład spokojny wtorkowy wieczór. Poza oknem karty zmiany nie da się zakończyć, chyba że to sytuacja awaryjna.","also":["okna zmian","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Szybkie głosowanie tuż przed wypuszczeniem zmiany: każda osoba, która musi ją zatwierdzić, mówi Go albo No go. Zmiana idzie dalej tylko wtedy, gdy wszyscy się zgadzają.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Zatwierdzenie","text":"Czekanie na „tak”, zanim praca się zacznie. Karta zgłoszona przez znajomego albo zmiana czeka w ✅ Zatwierdzeniach, aż ją zatwierdzisz albo odrzucisz.","also":["zatwierdzenia","akceptacja"]},{"id":"quiettime","g":"change","word":"Cicha pora","text":"Okres, na przykład stream, demo albo noc, w którym nic nie idzie na żywo. Zespoły dalej pracują i testują, ale wypuszczanie czeka, aż się skończy. Gdzie indziej nazywa się to zamrożeniem zmian.","also":["ciche pory","zamrożenie zmian","change freeze"]},{"id":"service","g":"run","word":"Usługa","text":"Coś zbudowanego przez Ciebie, na czym ludzie polegają, na przykład strona albo aplikacja, pilnowane tak, żeby dalej działało. Zaznacz „Ten projekt jest usługą” i napisz, co oferuje, kto z niej korzysta i kto ma dyżur.","also":["usługi","serwis"]},{"id":"uptime","g":"run","word":"Sprawdzanie dostępności","text":"Automatyczne sprawdzenie co kilka minut, czy Twoja usługa wciąż odpowiada. Jeśli kilka razy z rzędu się nie uda, AI-gile sam otwiera kartę incydentu.","also":["uptime","dostępność","uptime check"]},{"id":"statuspage","g":"run","word":"Strona statusu","text":"Publiczna strona, która pokazuje, czy usługa działa (zielony, pomarańczowy albo czerwony), z najnowszą informacją, żeby jej użytkownicy mogli sprawdzić, zamiast pytać.","also":["strony statusu","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Where questions and reports from the people using your service come in. AI-gile sorts each one into a request, an incident or an idea, and says so when it looks like something already reported.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Someone asking for something ordinary, like a new account or a bit of help, rather than reporting that something is broken. It waits its turn; an incident goes first.","also":["service requests"]},{"id":"incident","g":"run","word":"Incydent","text":"Coś, co właśnie teraz nie działa dla ludzi, którzy z tego korzystają, na przykład strona leży. Karta 🔥 incydentu wskakuje na początek kolejki: najpierw trzeba to znowu uruchomić.","also":["incydenty","awaria"]},{"id":"major","g":"run","word":"Poważny incydent","text":"Duży incydent: dotyka wielu ludzi albo zagraża pieniądzom lub danym. Jeden przycisk rzuca na niego wszystkie zespoły (rój), budzi dyżurnego i co 30 minut prosi o informację o stanie.","also":["poważne incydenty","major incident"]},{"id":"oncall","g":"run","word":"Dyżur","text":"Bycie osobą, która reaguje, gdy coś się zepsuje, nawet w nocy. Każda usługa ma dyżurnego członka zespołu, którego budzi się jako pierwszego przy jej incydentach.","also":["dyżurny","on call","on-call","w pogotowiu"]},{"id":"replyby","g":"run","word":"Termin odpowiedzi","text":"Jak długo karta może czekać na pierwszą odpowiedź, na przykład godzinę przy incydencie. Potem dostaje czerwony zegar, żeby nic nie zostało po cichu zapomniane. Nazywa się to też docelowym czasem reakcji.","also":["terminy odpowiedzi","czas reakcji","docelowy czas reakcji"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Krótka analiza po incydencie: co się stało, co pomogło i co zmienić, bez obwiniania kogokolwiek. Incydentu nie da się zamknąć bez niej.","also":["analiza poincydentalna","postmortem","przegląd po incydencie"]},{"id":"problem","g":"run","word":"Problem","text":"Ukryta przyczyna jednego lub kilku incydentów. Karta 🧩 problemu grupuje incydenty, które ciągle wracają, żeby przyczynę znaleźć i naprawić na dobre.","also":["problemy"],"noTip":1},{"id":"rootcause","g":"run","word":"Przyczyna źródłowa","text":"Prawdziwy powód, dla którego coś się zepsuło, a nie tylko to, co było widać. Napraw przyczynę źródłową, a incydent przestanie wracać.","also":["przyczyny źródłowe","root cause","pierwotna przyczyna"]},{"id":"workaround","g":"run","word":"Obejście","text":"Sposób, żeby wszystko działało, zanim będzie gotowa prawdziwa naprawa, na przykład restart czegoś, co się zawiesza. Zapisuje się je na karcie problemu, żeby nikt nie musiał wymyślać go od nowa.","also":["obejścia","workaround","rozwiązanie tymczasowe"]},{"id":"knownerror","g":"run","word":"Znany błąd","text":"Problem, którego przyczyna jest znana i który ma obejście, ale nie jest jeszcze naprawiony. 🧩 Znane błędy je wymienia, żeby każdy korzystał z obejścia, zamiast szukać od nowa.","also":["znane błędy","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Instrukcja krok po kroku, jak naprawić znany rodzaj kłopotu, żeby za każdym razem robić to tak samo i szybko. Po dużym incydencie zespół może zaproponować taki runbook do Twojej akceptacji.","also":["runbooki","instrukcja postępowania","procedura"]},{"id":"ci","g":"run","word":"Configuration item","text":"One thing your service depends on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists them per service, so you can see what an incident affects and what needs renewing or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"AI-gile keeps an eye on dates like when a certificate or a domain runs out. Within 30 days of the date it makes one card to renew it, so nothing stops working by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"Kopia zapasowa","text":"Zapisana wcześniej kopia Twoich danych, na wypadek gdyby coś zginęło albo się uszkodziło. AI-gile codziennie robi kopię zapasową Twoich tablic.","also":["kopie zapasowe","backup","backupy"]},{"id":"restore","g":"run","word":"Przywracanie","text":"Odtwarzanie danych z kopii zapasowej. Kopia naprawdę się liczy dopiero wtedy, gdy wiesz, że da się ją przywrócić, więc warto to czasem sprawdzić.","also":["przywrócenie","przywrócone","restore"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at one month of a service: incidents opened and fixed, how quickly people got an answer, uptime and tokens used. The Monthly review shows it for each service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checking every 90 days who can still get in: share links, friends’ roles and kept secrets. You keep or remove each one, so old access doesn’t linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Everything the team decided to get better at, in one place: retro suggestions, review actions and problem fixes, each with its status. Find it under 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service’s agents may use. At 80% you get a warning; at 100% their background work waits until next month or until you raise the cap.","also":["token caps"]},{"id":"backlog","g":"team","word":"Backlog","text":"Pomysły i praca jeszcze niezaplanowana. Nic stamtąd nie jest robione, dopóki nie trafi do kolumny Do zrobienia."},{"id":"sprint","g":"team","word":"Sprint","text":"Krótki odcinek pracy (często tydzień lub dwa) z uzgodnionym zestawem kart do skończenia.","also":["sprinty","sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Krótka odprawa: co każdy zrobił, co zrobi dalej i co go blokuje.","also":["standup","stand-upy","standupy"]},{"id":"kanban","g":"team","word":"Kanban","text":"Tablica z kolumnami (Do zrobienia, W toku, Gotowe), po której karty przesuwają się od lewej do prawej w miarę pracy."},{"id":"wip","g":"team","word":"Limit WIP","text":"Work in progress: najwięcej kart, jakie powinna mieć kolumna, żeby zespół kończył rzeczy, zanim zacznie kolejne.","also":["WIP"]},{"id":"dod","g":"team","word":"Definicja Zrobione","text":"Krótka lista zespołu, co znaczy „skończone”, na przykład przetestowane i wyjaśnione, zanim karta trafi do Ciebie. Jej bliźniaczka, Definicja Gotowe do startu, mówi, kiedy karta jest na tyle jasna, żeby zacząć.","also":["Definition of Done","DoD","Definicja Gotowe do startu","Definition of Ready"]},{"id":"testpile","g":"team","word":"Stos testów","text":"Gotowe karty, które czekają, aż je wypróbujesz, jedna po drugiej. Zaakceptuj jedną albo odeślij ją z notatką, a pojawi się następna.","also":["stosy testów","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Spojrzenie wstecz na to, jak pracuje zespół, żeby ustalić jedną rzecz do poprawy. W AI-gile retro proponuje zmianę w sposobie pracy zespołu, a Ty mówisz Go albo Jeszcze nie.","also":["retrospektywa","retrospektywy"]},{"id":"peerreview","g":"team","word":"Recenzja przez innych","text":"Druga para oczu: inne AI sprawdza pracę z każdej karty, zanim trafi do Ciebie, więc mniej błędów przechodzi dalej.","also":["peer review","code review","przegląd kodu"]},{"id":"swarm","g":"team","word":"Rój","text":"Wszystkie ręce na pokład: każdy zespół odkłada inną pracę i pomaga przy jednym pilnym projekcie, dopóki sprawa nie zostanie załatwiona. Inne projekty w tym czasie czekają.","also":["tryb roju","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Ktoś, kto dba o płynność pracy: wyłapuje utknięte karty, popędza zespoły i przypomina Ci, co czeka. W AI-gile Lead Scrum Master robi to we wszystkich projektach.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI, które samo pracuje nad zadaniem: czyta kod, wprowadza zmiany, uruchamia sprawdzenia i melduje się z wynikami.","also":["agenci"]},{"id":"token","g":"team","word":"Token","text":"Jednostka, w której liczy się zużycie AI: mniej więcej kilka liter przeczytanego lub napisanego tekstu. Mniej tokenów, więcej planu zostaje.","also":["tokeny"]},{"id":"hook","g":"team","word":"Hook","text":"Małe polecenie, które uruchamia się samo w ustalonym momencie, np. gdy startuje sesja AI, żeby zespół usłyszał Twoje komentarze.","also":["hooki","haki"]}]}};
